      '401': apiErrorResponse(401),
      '404': apiErrorResponse(404),
      '409': apiErrorResponse(409),
      '500': apiErrorResponse(500),
    },
  }),
  apiValidator('param', DeviceParamsSchema),
  apiValidator('json', UpdateDeviceInputSchema),
  async (context) => {
